public static void commonTick(Level level, BlockPos worldPosition, BlockState state, HoveringHourglassBlockEntity self) {
		int totalTime = self.getTotalTime();
		boolean dust = self.isDust();

		if (totalTime > 0 || dust) {
			if (self.move && !dust) {
				self.time++;
			}

			if (self.time >= totalTime) {
				self.time = 0;
				self.flip = !self.flip;
				self.flipTicks = 4;
				if (!level.isClientSide) {
					level.setBlock(worldPosition, state.setValue(BlockStateProperties.POWERED, true), Block.UPDATE_NEIGHBORS);
					level.scheduleTick(worldPosition, state.getBlock(), 4);
				}

				for (Direction facing : Direction.values()) {
					BlockPos pos = worldPosition.relative(facing);
					var trigger = XplatAbstractions.INSTANCE.findHourglassTrigger(level, pos,
							level.getBlockState(pos), level.getBlockEntity(pos));
					if (trigger != null) {
						trigger.onTriggeredByHourglass(self);
					}
				}
			}

			self.lastFraction = self.timeFraction;
			self.timeFraction = (float) self.time / (float) totalTime;
		} else {
			self.time = 0;
			self.lastFraction = 0F;
			self.timeFraction = 0F;
		}

		if (self.flipTicks > 0) {
			self.flipTicks--;
		}
	}

private boolean isDust() {
		ItemStack stack = getItemHandler().getItem(0);
		return !stack.isEmpty() && stack.is(BotaniaItems.manaPowder);
	}

@Override
	public void onBurstCollision(ManaBurst burst) {
		if (!level.isClientSide && !burst.isFake()) {
			if (isDust()) {
				time++;
			} else {
				move = !move;
			}
			VanillaPacketDispatcher.dispatchTEToNearbyPlayers(this);
		}
	}

public int getTotalTime() {
		ItemStack stack = getItemHandler().getItem(0);
		if (stack.isEmpty()) {
			return 0;
		}

		return getStackItemTime(stack) * stack.getCount();
	}

public static int getStackItemTime(ItemStack stack) {
		if (stack.isEmpty()) {
			return 0;
		}
		if (stack.is(Blocks.SAND.asItem())) {
			return 20;
		}
		if (stack.is(Blocks.RED_SAND.asItem())) {
			return 200;
		}
		if (stack.is(Blocks.SOUL_SAND.asItem())) {
			return 1200;
		}
		if (stack.is(BotaniaItems.manaPowder)) {
			return 1;
		}
		return 0;
	}

@Override
	public void setChanged() {
		super.setChanged();
		if (level != null && !level.isClientSide) {
			time = 0;
			timeFraction = 0F;
			VanillaPacketDispatcher.dispatchTEToNearbyPlayers(HoveringHourglassBlockEntity.this);
		}
	}

@Override
	public void writePacketNBT(CompoundTag tag) {
		super.writePacketNBT(tag);
		tag.putInt(TAG_TIME, time);
		tag.putFloat(TAG_TIME_FRACTION, timeFraction);
		tag.putBoolean(TAG_FLIP, flip);
		tag.putInt(TAG_FLIP_TICKS, flipTicks);
		tag.putBoolean(TAG_MOVE, move);
		tag.putBoolean(TAG_LOCK, lock);
	}

@Override
	public void readPacketNBT(CompoundTag tag) {
		super.readPacketNBT(tag);
		time = tag.getInt(TAG_TIME);
		timeFraction = tag.getFloat(TAG_TIME_FRACTION);
		flip = tag.getBoolean(TAG_FLIP);
		flipTicks = tag.getInt(TAG_FLIP_TICKS);
		move = tag.getBoolean(TAG_MOVE);
		lock = tag.getBoolean(TAG_LOCK);
	}

@Override
	public boolean onUsedByWand(@Nullable Player player, ItemStack stack, Direction side) {
		this.lock = !this.lock;
		if (!getLevel().isClientSide) {
			VanillaPacketDispatcher.dispatchTEToNearbyPlayers(this);
		}
		return true;
	}

@Override
	public InteractionResult use(BlockState state, Level world, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hit) {
		if (!(world.getBlockEntity(pos) instanceof HoveringHourglassBlockEntity hourglass)) {
			return InteractionResult.FAIL;
		}
		ItemStack hgStack = hourglass.getItemHandler().getItem(0);
		ItemStack stack = player.getItemInHand(hand);
		if (!stack.isEmpty() && stack.getItem() instanceof WandOfTheForestItem) {
			return InteractionResult.PASS;
		}

		if (hourglass.lock) {
			if (!player.level().isClientSide && hand == InteractionHand.OFF_HAND) {
				player.sendSystemMessage(Component.translatable("botaniamisc.hourglassLock"));
			}
			return InteractionResult.FAIL;
		}

		if (hgStack.isEmpty() && HoveringHourglassBlockEntity.getStackItemTime(stack) > 0) {
			hourglass.getItemHandler().setItem(0, stack.copy());
			stack.setCount(0);
			return InteractionResult.sidedSuccess(world.isClientSide());
		} else if (!hgStack.isEmpty()) {
			player.getInventory().placeItemBackInInventory(hgStack);
			hourglass.getItemHandler().setItem(0, ItemStack.EMPTY);
			return InteractionResult.sidedSuccess(world.isClientSide());
		}

		return InteractionResult.PASS;
	}

@Override
	public void tick(BlockState state, ServerLevel world, BlockPos pos, RandomSource rand) {
		if (state.getValue(BlockStateProperties.POWERED)) {
			world.setBlockAndUpdate(pos, state.setValue(BlockStateProperties.POWERED, false));
		}
	}

@Nullable
	@Override
	public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level, BlockState state, BlockEntityType<T> type) {
		return createTickerHelper(type, BotaniaBlockEntities.HOURGLASS, HoveringHourglassBlockEntity::commonTick);
	}

@Override
	public int getSignal(BlockState state, BlockGetter world, BlockPos pos, Direction side) {
		return state.getValue(BlockStateProperties.POWERED) ? 15 : 0;
	}

@Override
	public void onRemove(@NotNull BlockState state, @NotNull Level world, @NotNull BlockPos pos, @NotNull BlockState newState, boolean isMoving) {
		if (!state.is(newState.getBlock())) {
			if (world.getBlockEntity(pos) instanceof SimpleInventoryBlockEntity inventory) {
				Containers.dropContents(world, pos, inventory.getItemHandler());
			}
			super.onRemove(state, world, pos, newState, isMoving);
		}
	}

@Override
    public void tick(Level level) {
        if (!(level instanceof ServerLevel serverLevel))
            return;

        if (!isActive()) {
            if (this.nextSandstorm == -1)
                this.nextSandstorm = serverLevel.getGameTime() + this.interval.sample(serverLevel.getRandom());

            if (this.nextSandstorm <= serverLevel.getGameTime())
                start(serverLevel);

            return;
        }

        if (this.sandstormEndTime >= 0 && this.sandstormEndTime <= serverLevel.getGameTime()) {
            stop(serverLevel);

            return;
        }

        if (getIntensity(serverLevel.getGameTime()) >= 1 && serverLevel.getGameTime() % 10 == 0) {
            DamageSource source = DamageUtil.miscDamage(AoADamageTypes.SANDSTORM, serverLevel);

            Streams.stream(serverLevel.getEntities().getAll())
                    .filter(LivingEntity.class::isInstance)
                    .map(LivingEntity.class::cast)
                    .filter(this::isEntityAffected)
                    .forEach(entity -> entity.hurt(source, this.damage.sample(serverLevel.getRandom())));
        }
    }

@Override
    public void start(ServerLevel level) {
        this.active = true;
        this.sandstormStartTime = level.getGameTime();
        this.sandstormEndTime = this.sandstormStartTime + this.duration.sample(level.getRandom());

        markDirty(level);
    }

@Override
    public void stop(ServerLevel level) {
        this.active = false;
        this.nextSandstorm = level.getGameTime() + this.interval.sample(level.getRandom());
        this.sandstormEndTime = -1;
        this.sandstormStartTime = -1;

        markDirty(level);
    }

@Override
    public CompoundTag save() {
        CompoundTag tag = new CompoundTag();

        tag.putBoolean("Active", this.active);
        tag.putLong("NextSandstorm", this.nextSandstorm);
        tag.putLong("SandstormEndTime", this.sandstormEndTime);
        tag.putLong("SandstormStartTime", this.sandstormStartTime);

        return tag;
    }

@Override
    public void load(CompoundTag tag) {
        this.active = tag.getBoolean("Active");
        this.nextSandstorm = tag.getLong("NextSandstorm");
        this.sandstormEndTime = tag.getLong("SandstormEndTime");
        this.sandstormStartTime = tag.getLong("SandstormStartTime");
    }

@Override
    public AoAWorldEvent copy() {
        return new BarathosSandstormEvent(this.baseSettings, this.interval, this.duration, this.damage);
    }

@Override
    public boolean shouldAddToDimension(ServerLevel level) {
        return this.baseSettings.dimensions().contains(level.dimension());
    }

public float getIntensity(long gameTime) {
        return Math.min(1f, Math.min((gameTime - this.sandstormStartTime) / 600f, (this.sandstormEndTime - gameTime) / 100f));
    }

public boolean isEntityAffected(LivingEntity entity) {
        return NumberUtil.numberIsBetween(entity.getY(), 90, 125) && entity.level().getBrightness(LightLayer.SKY, entity.blockPosition()) == 15 && !entity.getType().is(AoATags.Entities.IMMUNE_TO_SANDSTORM) && (!(entity instanceof Player) || entity.tickCount > 60);
    }

public static AoAWorldEventManager getForLevel(Level level) {
        if (level.isClientSide)
            return CLIENT_INSTANCE;

        return ((ServerLevel)level).getDataStorage().computeIfAbsent(FACTORY, DATA_KEY);
    }

public static void load(ServerLevel level) {
        List<AoAWorldEvent> events = level.getServer().registryAccess().registryOrThrow(AoARegistries.WORLD_EVENTS_REGISTRY_KEY).stream()
                .filter(event -> event.shouldAddToDimension(level))
                .map(AoAWorldEvent::copy)
                .toList();

        if (!events.isEmpty()) {
            AoAWorldEventManager manager = getForLevel(level);

            for (AoAWorldEvent event : events) {
                manager.events.put(event.getId(), event);
            }

            if (manager.initData != null) {
                for (AoAWorldEvent event : manager.events.values()) {
                    if (manager.initData.contains(event.getId().toString()))
                        event.load(manager.initData.getCompound(event.getId().toString()));
                }

                manager.initData = null;
            }
        }
    }

public static void tick(Level level) {
        getForLevel(level).events.values().forEach(ev -> ev.tick(level));
    }

@Override
    public CompoundTag save(CompoundTag tag, HolderLookup.Provider registries) {
        for (AoAWorldEvent event : this.events.values()) {
            CompoundTag saveData = event.save();

            if (saveData != null)
                tag.put(event.getId().toString(), saveData);
        }

        return tag;
    }

public static void markDirty(ServerLevel level) {
        getForLevel(level).setDirty();
    }

public static void syncFromServer(AoAWorldEvent.Type<?> eventType, ResourceLocation id, CompoundTag tag) {
        CLIENT_INSTANCE.events.computeIfAbsent(id, key -> eventType.clientConstructor().get()).load(tag);
    }

default void markDirty(ServerLevel level) {
        AoAWorldEventManager.markDirty(level);
        AoANetworking.sendToAllInLevel(level, new WorldEventUpdatePacket(getType(), getId(), save()));
    }

public static void preInit() {
		final IEventBus forgeBus = NeoForge.EVENT_BUS;

		forgeBus.addListener(EventPriority.NORMAL, false, ServerTickEvent.Post.class, GlobalEvents::serverTick);
		forgeBus.addListener(EventPriority.NORMAL, false, ModifyCustomSpawnersEvent.class, GlobalEvents::addCustomSpawners);
		forgeBus.addListener(EventPriority.NORMAL, false, LevelEvent.Load.class, GlobalEvents::levelLoad);
		forgeBus.addListener(EventPriority.NORMAL, false, LevelTickEvent.Pre.class, GlobalEvents::levelTick);
		forgeBus.addListener(EventPriority.NORMAL, false, ServerStartingEvent.class, GlobalEvents::serverStarting);
		forgeBus.addListener(EventPriority.NORMAL, false, ServerStartedEvent.class, GlobalEvents::serverStarted);
		forgeBus.addListener(EventPriority.NORMAL, false, ServerStoppingEvent.class, GlobalEvents::serverStopping);
		forgeBus.addListener(EventPriority.NORMAL, false, TagsUpdatedEvent.class, GlobalEvents::datapackUpdate);
	}

private static void levelTick(final LevelTickEvent.Pre ev) {
		AoAWorldEventManager.tick(ev.getLevel());
	}

private static void levelLoad(final LevelEvent.Load ev) {
		if (ev.getLevel() instanceof ServerLevel level)
			AoAWorldEventManager.load(level);
	}

@Override
	public void receiveMessage(IPayloadContext context) {
		context.enqueueWork(() -> AoAWorldEventManager.syncFromServer(this.eventType, this.eventId, this.data));
	}
